import java.util.Scanner;
public class BinarySearch { public static int search(int[]a,int target){int l=0,r=a.length-1;while(l<=r){int m=l+(r-l)/2;if(a[m]==target)return m;if(a[m]<target)l=m+1;else r=m-1;}return -1;} public static void main(String[]args){Scanner sc=new Scanner(System.in);System.out.print("Enter sorted array size: ");int n=sc.nextInt();if(n<0){System.out.println("Invalid size.");sc.close();return;}int[]a=new int[n];System.out.println("Enter sorted elements:");for(int i=0;i<n;i++)a[i]=sc.nextInt();System.out.print("Target: ");int target=sc.nextInt();System.out.println("Index: "+search(a,target));sc.close();} }